package com.papazone.ai;

import com.papazone.ai.security.JwtVerifier;
import org.junit.jupiter.api.Test;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tokens below were generated by an independent HMAC implementation (Python), not by this code. */
class JwtVerifierTest {

    // "now" = 6 Nov 2026
    private static final Clock CLOCK = Clock.fixed(Instant.parse("2026-11-06T10:00:00Z"), ZoneOffset.UTC);

    private static final String SECRET256 =
            "MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=";
    private static final String ADMIN256 =
            "eyJhbGciOiAiSFMyNTYifQ.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogNywgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQURNSU4iLCAiaWF0IjogMTcwMDAwMDAwMCwgImV4cCI6IDQxMDI0NDQ4MDB9.N8el2Bs62gKxuLwJkk6TI6qmFdEc9f9Y2F0gHMAC6P4";
    private static final String CUSTOMER256 =
            "eyJhbGciOiAiSFMyNTYifQ.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogOSwgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQ1VTVE9NRVIiLCAiaWF0IjogMTcwMDAwMDAwMCwgImV4cCI6IDQxMDI0NDQ4MDB9.vP054CLFk6QLG0psVzikz7N5oixFqEC93J1-0vAlNGA";
    private static final String EXPIRED256 =
            "eyJhbGciOiAiSFMyNTYifQ.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogNywgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQURNSU4iLCAiaWF0IjogMTcwMDAwMDAwMCwgImV4cCI6IDE3MDAwMDAxMDB9.3ONwtn_Pl2syjGFa-IY0r32My7xlMFnFHCfG7Mn1GXQ";
    private static final String NOEXP256 =
            "eyJhbGciOiAiSFMyNTYifQ.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogNywgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQURNSU4iLCAiaWF0IjogMTcwMDAwMDAwMH0.UUjs3uPzzbCauc9Xt7Sz03L9xo3MCCcnXSuOWYQYfag";
    private static final String WRONGKEY256 =
            "eyJhbGciOiAiSFMyNTYifQ.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogNywgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQURNSU4iLCAiaWF0IjogMTcwMDAwMDAwMCwgImV4cCI6IDQxMDI0NDQ4MDB9.9WkJ0n561vDNLXTMTLpv25Y8R5MfngBTE8tZ93r8Un0";
    private static final String SECRET512 =
            "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8gISIjJCUmJygpKissLS4vMDEyMzQ1Njc4OTo7PD0+Pw==";
    private static final String ADMIN512 =
            "eyJhbGciOiAiSFM1MTIifQ.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogNywgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQURNSU4iLCAiaWF0IjogMTcwMDAwMDAwMCwgImV4cCI6IDQxMDI0NDQ4MDB9.scCsJe-CMANsgfItB72m5mpEERdfW4afWz_UQzoekOdi86jcMMBiV4oD_obTXTEGq6-kdvT5GawzcGE3qfAJQw";
    private static final String ALGNONE =
            "eyJhbGciOiAibm9uZSJ9.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogNywgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQURNSU4iLCAiaWF0IjogMTcwMDAwMDAwMCwgImV4cCI6IDQxMDI0NDQ4MDB9.";
    private static final String TAMPERED =
            "eyJhbGciOiAiSFMyNTYifQ.eyJzdWIiOiAiNyIsICJjdXN0b21lcklkIjogMSwgImVtYWlsIjogImFAYi5jIiwgInJvbGUiOiAiQURNSU4iLCAiaWF0IjogMTcwMDAwMDAwMCwgImV4cCI6IDQxMDI0NDQ4MDB9.N8el2Bs62gKxuLwJkk6TI6qmFdEc9f9Y2F0gHMAC6P4";

    private final JwtVerifier v256 = new JwtVerifier(SECRET256, CLOCK);

    @Test
    void acceptsValidHs256AdminToken() {
        JwtVerifier.Claims c = v256.verify(ADMIN256).orElseThrow();

        assertEquals(7L, c.customerId());
        assertEquals("a@b.c", c.email());
        assertTrue(c.isAdmin());
    }

    @Test
    void acceptsValidHs512TokenWhenSecretIsLong() {
        assertTrue(new JwtVerifier(SECRET512, CLOCK).verify(ADMIN512).isPresent());
    }

    @Test
    void customerTokenIsNotAdmin() {
        JwtVerifier.Claims c = v256.verify(CUSTOMER256).orElseThrow();

        assertEquals(9L, c.customerId());
        assertFalse(c.isAdmin());
    }

    @Test
    void rejectsTamperedExpiredUnsignedAndWrongKeyTokens() {
        assertTrue(v256.verify(TAMPERED).isEmpty());
        assertTrue(v256.verify(EXPIRED256).isEmpty());
        assertTrue(v256.verify(NOEXP256).isEmpty());
        assertTrue(v256.verify(ALGNONE).isEmpty());
        assertTrue(v256.verify(WRONGKEY256).isEmpty());
        assertTrue(new JwtVerifier(SECRET512, CLOCK).verify(ADMIN256).isEmpty());
    }

    @Test
    void rejectsGarbageAndNeverThrows() {
        assertTrue(v256.verify(null).isEmpty());
        assertTrue(v256.verify("").isEmpty());
        assertTrue(v256.verify("a.b").isEmpty());
        assertTrue(v256.verify("!!!.???.***").isEmpty());
    }

    @Test
    void blankSecretDisablesEverything() {
        JwtVerifier off = new JwtVerifier("", CLOCK);

        assertFalse(off.enabled());
        assertTrue(off.verify(ADMIN256).isEmpty());
    }

    @Test
    void readsBearerHeaderCaseInsensitively() {
        assertTrue(v256.verifyAuthorizationHeader("Bearer " + ADMIN256).isPresent());
        assertTrue(v256.verifyAuthorizationHeader("bearer " + ADMIN256).isPresent());
        assertTrue(v256.verifyAuthorizationHeader(ADMIN256).isEmpty());
        assertTrue(v256.verifyAuthorizationHeader(null).isEmpty());
    }
}
